    return vmax * s / (km + s + s * s / ki)

def estimate_variant_haldane_parameters(plates: list[dict]) -> dict[str, dict[str, float]]:
    """Estimate positive V_max, K_m, and K_i for each variant across plates."""
    from scipy.optimize import least_squares
    groups = {}
    for plate in plates:
        wells = plate['wells']
        (offset, gain, scale) = _calibrate(wells)
        for w in wells:
            if w['well_type'] == 'VARIANT':
                g = np.dot(_basis(w['row'], w['col']), gain)
                groups.setdefault(w['variant_id'], []).append((w['substrate_mM'], _raw(w) - offset, g, scale))
    results = {}
    for (variant, rows) in groups.items():
        (s, y, g, scale) = np.asarray(rows).T
        (lo, hi) = (min(s[s > 0]), max(s))
        v = max(np.percentile(y / g, 85), 1e-06)
        initial = np.log([2 * v, np.sqrt(lo * hi) / 2, np.sqrt(lo * hi) * 2])
        lower = np.log([v * 0.0001, lo * 1e-05, lo * 1e-05])
        upper = np.log([v * 100000.0, hi * 100000.0, hi * 100000.0])
        fit = least_squares(lambda p: (g * _rate(s, p) - y) / scale, initial, bounds=(lower, upper), loss='soft_l1', f_scale=1.5)
        residual = (g * _rate(s, fit.x) - y) / scale
        keep = np.abs(residual - np.median(residual)) <= 4.5 * max(1.0, _mad(residual))
        if not keep.all() and np.unique(s[keep & (s > 0)]).size >= 3:
            fit = least_squares(lambda p: ((g * _rate(s, p) - y) / scale)[keep], fit.x, bounds=(lower, upper), loss='soft_l1', f_scale=2.5)
        results[variant] = dict(zip(('V_max', 'K_m', 'K_i'), map(float, np.exp(fit.x))))
    return results
